extension StringExtension on String {
  String capitalize() => isEmpty ? '' : '${this[0].toUpperCase()}${substring(1)}';
}

String formatStatus(Status status) => switch (status) {
  Status.active => 'Account is Active',
  Status.pending => 'Verification Pending',
  Status.suspended => 'Access Suspended',
};

Future<List<Item>> fetchItems() async {
  try {
    final response = await client.get(Uri.parse(endpoint));
    if (response.statusCode == 200) {
      final list = jsonDecode(response.body) as List;
      return list.map((e) => Item.fromJson(e)).toList();
    }
    throw ApiException('Failed with status: ${response.statusCode}');
  } finally {
    client.close();
  }
}

Stream<int> countStream(int max) async* {
  for (var i = 1; i <= max; i++) {
    await Future.delayed(const Duration(milliseconds: 100));
    yield i;
  }
}

sealed class AuthState {}
class AuthLoading extends AuthState {}
class Authenticated extends AuthState {
  final User user;
  Authenticated(this.user);
}
class Unauthenticated extends AuthState {}

class Debouncer {
  final Duration delay;
  Timer? _timer;
  Debouncer({required this.delay});

  void run(VoidCallback action) {
    _timer?.cancel();
    _timer = Timer(delay, action);
  }

  void dispose() => _timer?.cancel();
}

abstract interface class Cache<K, V> {
  V? get(K key);
  void set(K key, V value);
  void clear();
}

StreamTransformer<String, String> lineSplitter() {
  return StreamTransformer.fromHandlers(
    handleData: (data, sink) {
      for (final line in data.split('\n')) sink.add(line.trim());
    },
  );
}
